/**
 * SDK instance creation, operator deployment, and evidence contract bytecode.
 */

import {
  deployMarketplaceOperator,
  refundRequestEvidenceAbi,
} from '@x402r/core'
import {
  type ArbiterClient,
  createArbiterClient,
  createMerchantClient,
  createX402r,
  type MerchantClient,
  type X402r,
} from '@x402r/sdk'
import { type Address, createWalletClient, http } from 'viem'
import { baseSepolia } from 'viem/chains'

import type { E2EAccounts } from './accounts.js'
import { RPC_URL, waitForTx } from './config.js'
import type { StepRunner } from './runner.js'

// ============ Evidence Contract Bytecode (inline) ============
// Source: x402r-contracts/out/RefundRequestEvidence.sol/RefundRequestEvidence.json → bytecode.object
// Inlined to avoid cross-repo filesystem dependency at runtime.

const EVIDENCE_BYTECODE: `0x${string}` =
  '0x60a034607657601f61120138819003918201601f19168301916001600160401b03831184841017607a5780849260209460405283398101031260765751600160' +
  '0160a01b03811690819003607657608052604051611172908161008f82396080518181816103fb0152818161084c01526110950152f35b5f80fd5b634e487b7160' +
  'e01b5f52604160045260245ffdfe6080806040526004361015610012575f80fd5b5f3560e01c9081633216d6ab1461087b5750806353c3220814610837578063872f' +
  '69051461034a57806388d1117e146102b45763c622ee7d14610053575f80fd5b346102705736600319016101c081126102705761018013610270576101a43561007a' +
  '610bec565b50600460206001600160a01b0361008f610a03565b1660405192838092637340e25560e11b82525afa90811561027c57610184916020915f91610287575b' +
  '5060405163063a70ff60e01b815292839182906100d760048301610a76565b6001600160a01b03165afa90811561027c575f91610246575b506040516020810191825261' +
  ''

// ============ Types ============

interface DeployResult {
  operatorAddress: Address
  escrowPeriodAddress: Address
  freezeAddress: Address | null
  refundRequestAddress: Address
  refundInEscrowConditionAddress: Address
  refundRequestEvidenceAddress: Address
  feeCalculatorAddress: Address | null
  summary: {
    newCount: number
    existingCount: number
    txHashes: `0x${string}`[]
  }
}

interface SDKInstances {
  payer: X402r
  merchant: MerchantClient
  arbiter: ArbiterClient | undefined
}

// ============ Operator Deployment ============

export async function deployTestOperator(
  accounts: E2EAccounts,
  runner: StepRunner,
): Promise<DeployResult> {
  const { payerAccount, arbiterAccount, publicClient, chainId } = accounts

  // Fresh wallet client to avoid stale nonce from prior funding transactions
  const deployWallet = createWalletClient({
    account: payerAccount,
    chain: baseSepolia,
    transport: http(RPC_URL),
  })

  const deployResult = await deployMarketplaceOperator(
    deployWallet,
    publicClient,
    {
      chainId,
      feeRecipient: payerAccount.address,
      arbiter: (arbiterAccount ?? payerAccount).address,
      escrowPeriodSeconds: 604800n,
      freezeDurationSeconds: 259200n,
      operatorFeeBps: 100n,
    },
  )

  runner.log(`Operator: ${deployResult.operatorAddress}`)
  runner.pass(
    'Deploy operator',
    deployResult.summary.txHashes.length > 0
      ? deployResult.summary.txHashes[0]
      : undefined,
  )

  // Deploy RefundRequestEvidence bound to the per-arbiter RefundRequest
  // Wait for RPC nonce to catch up after multicall batch deploy
  await new Promise((r) => setTimeout(r, 3000))
  runner.log('Deploying RefundRequestEvidence...')
  const evidenceWallet = createWalletClient({
    account: payerAccount,
    chain: baseSepolia,
    transport: http(RPC_URL),
  })
  const evidenceDeployTx = await evidenceWallet.deployContract({
    abi: refundRequestEvidenceAbi,
    bytecode: EVIDENCE_BYTECODE,
    args: [deployResult.refundRequestAddress],
    account: payerAccount,
    chain: baseSepolia,
  })
  await waitForTx(publicClient, evidenceDeployTx)
  const evidenceReceipt = await publicClient.getTransactionReceipt({
    hash: evidenceDeployTx,
  })
  const evidenceAddress = evidenceReceipt.contractAddress as Address
  runner.log(`  RefundRequestEvidence: ${evidenceAddress}`)
  runner.pass('Deploy RefundRequestEvidence', evidenceDeployTx)

  return {
    operatorAddress: deployResult.operatorAddress,
    escrowPeriodAddress: deployResult.escrowPeriodAddress,
    freezeAddress: deployResult.freezeAddress,
    refundRequestAddress: deployResult.refundRequestAddress,
    refundInEscrowConditionAddress: deployResult.refundInEscrowConditionAddress,
    refundRequestEvidenceAddress: evidenceAddress,
    feeCalculatorAddress: deployResult.feeCalculatorAddress,
    summary: deployResult.summary,
  }
}

// ============ SDK Instance Creation (role-scoped presets) ============

export function createSDKInstances(
  accounts: E2EAccounts,
  deployResult: DeployResult,
): SDKInstances {
  const { publicClient, payerWallet, merchantWallet, arbiterWallet, chainId } =
    accounts
  const opAddr = deployResult.operatorAddress
  const refundRequestAddress = deployResult.refundRequestAddress
  const freezeAddr = deployResult.freezeAddress ?? undefined
  const escrowPeriodAddr = deployResult.escrowPeriodAddress

  const commonConfig = {
    publicClient,
    operatorAddress: opAddr,
    chainId,
    refundRequestAddress,
    refundRequestEvidenceAddress: deployResult.refundRequestEvidenceAddress,
    escrowPeriodAddress: escrowPeriodAddr,
    freezeAddress: freezeAddr,
  }

  // Use createX402r for payer (needs full freeze access — payer initiates freezes)
  const payer = createX402r({
    ...commonConfig,
    walletClient: payerWallet,
  })
  const merchant = createMerchantClient({
    ...commonConfig,
    walletClient: merchantWallet,
  })
  const arbiter = arbiterWallet
    ? createArbiterClient({ ...commonConfig, walletClient: arbiterWallet })
    : undefined

  return { payer, merchant, arbiter }
}
